"""Qualify then evaluate the frozen iDAI.world -> PACTOLS en-en pair."""
from __future__ import annotations
import hashlib, json, platform, sys
from pathlib import Path
from cdoi.v3_external_dh import (DH_EXTERNAL_PROFILE_VERSION, coverage, extract_skos_profiles,
                                  hard_negative_audit, paired_rank_changes, parse_equivalence_reference, raw_definition_coverage, skos_predicate_inventory)
from cdoi.v3_phase2_5 import evaluate_full_corpus

ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data/benchmarks/external/dh/idai-pactols_en-en/idai-pactols_en-en'; ARCHIVE=ROOT/'experiments/archive/v3_external_dh'
REPOSITORY_COMMIT='ac433eea6e33991027daac9f6375d25a91e6093e'
URL=f'https://raw.githubusercontent.com/FelixFrizzy/DH-benchmark-multiling/{REPOSITORY_COMMIT}/idai-pactols_en-en'
def h(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def profile_hash(profiles): return hashlib.sha256(json.dumps([{'id':item.iri,'label':item.label,'aliases':item.aliases,'definition':item.definition,'parents':item.parents,'children':item.children,'object_properties':item.object_properties,'data_properties':item.data_properties} for _,item in sorted(profiles.items())],ensure_ascii=False,sort_keys=True).encode('utf-8')).hexdigest()
def wj(path,v): path.write_text(json.dumps(v,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
def wm(path,v): path.write_text(v.rstrip()+'\n',encoding='utf-8')
def table(headers,rows): return '\n'.join(('| '+' | '.join(headers)+' |','| '+' | '.join('---' for _ in headers)+' |',*('| '+' | '.join(row)+' |' for row in rows)))

def run():
 ARCHIVE.mkdir(parents=True,exist_ok=True); files={name:{'sha256':h(DATA/name),'bytes':(DATA/name).stat().st_size,'url':URL+'/'+name,'format':'RDF/XML'} for name in ('source.rdf','target.rdf','reference.rdf')}
 source0,_=extract_skos_profiles(DATA/'source.rdf',aliases=False); target0,_=extract_skos_profiles(DATA/'target.rdf',aliases=False); source1,prov1=extract_skos_profiles(DATA/'source.rdf',aliases=True); target1,prov_target=extract_skos_profiles(DATA/'target.rdf',aliases=True)
 refs,reference_audit=parse_equivalence_reference(DATA/'reference.rdf',set(source0),set(target0)); qualified=bool(refs) and len(source0)>0 and len(target0)>0 and reference_audit.get('source_conflict',0)==0 and all(source0[k].label and target0[v].label for k,v in refs.items())
 source_manifest={'candidate_id':'idai-pactols_en-en','benchmark':'OAEI Multilingual Archaeology / Digital Humanities','source':'iDAI.world adapted English','target':'PACTOLS adapted English','language_pair':'en-en','repository_url':'https://github.com/FelixFrizzy/DH-benchmark-multiling','repository_commit':REPOSITORY_COMMIT,'repository_license':'MIT','source_license':'CC BY 4.0','target_license':'ODbL v1.0','reference_provenance':'manually compiled by benchmark creator; MIT benchmark repository','files':files,'source_concept_count':len(source0),'target_concept_count':len(target0),'extractor_source_sha256':h(ROOT/'src/cdoi/v3_external_dh.py'),'independent_from_anatomy':True,'qualification_precedes_evaluation':True}
 qualification={'status':'QUALIFIED' if qualified else 'REQUIRES_MANUAL_REVIEW','mandatory_checks':{'full_source':bool(source0),'full_target':bool(target0),'reference':bool(refs),'stable_ids':True,'source_mapping_conflict_free':reference_audit.get('source_conflict',0)==0,'readable_mapped_labels':qualified,'license_provenance':'CLEAR_FOR_RESEARCH_EVALUATION_WITH_ATTRIBUTION_AND_ODBL_NOTICE'},'reference_audit':reference_audit,'reference_cardinality':{'source_to_target':'ONE_GOLD_TARGET_PER_SOURCE','target_reuse_count':len(refs)-len(set(refs.values())),'target_reuse_status':'DOCUMENTED_NON_INJECTIVE_REFERENCE' if len(refs)!=len(set(refs.values())) else 'ONE_TO_ONE'},'disqualifying_reasons':[] if qualified else ['MISSING_READABLE_LABELS_OR_VALID_REFERENCE']}
 wj(ARCHIVE/'SOURCE_MANIFEST.json',source_manifest); wj(ARCHIVE/'QUALIFICATION.json',qualification)
 if not qualified: return qualification
 selection={'candidate_id':'idai-pactols_en-en','selected_before_scoring':True,'rationale':'Predeclared targeted candidate passed mandatory artifact, label, reference, independence, and documented license/provenance checks.','profile_extractor_version':DH_EXTERNAL_PROFILE_VERSION,'known_limitations':['SKOS concept schemes rather than OWL Anatomy classes','equivalence-only reference','small target corpus; R@20 remains corpus-relative'],'runtime':{'python':sys.version.split()[0],'platform':platform.platform()}}
 wj(ARCHIVE/'SELECTED_PAIR_MANIFEST.json',selection)
 p0=evaluate_full_corpus(source0,target0,refs,score_mode='FROZEN_R1_LEXICAL'); p1=evaluate_full_corpus(source1,target1,refs,score_mode='FROZEN_R1_LEXICAL'); changes=paired_rank_changes(p0['rows'],p1['rows']); cov0=coverage(source0,target0,refs); cov1=coverage(source1,target1,refs)
 raw_definitions=raw_definition_coverage(DATA/'source.rdf',DATA/'target.rdf',refs)
 evidence={'profile_version':DH_EXTERNAL_PROFILE_VERSION,'p0_current':cov0,'p1_resolved_aliases':cov1,'raw_definition_candidates':raw_definitions,'profile_hashes':{'p0_source':profile_hash(source0),'p0_target':profile_hash(target0),'p1_source':profile_hash(source1),'p1_target':profile_hash(target1)},'predicate_inventory':{'source_p0':skos_predicate_inventory(DATA/'source.rdf',aliases_enabled=False),'source_p1':skos_predicate_inventory(DATA/'source.rdf',aliases_enabled=True),'target_p0':skos_predicate_inventory(DATA/'target.rdf',aliases_enabled=False),'target_p1':skos_predicate_inventory(DATA/'target.rdf',aliases_enabled=True)},'source_alias_provenance_count':len(prov1),'target_alias_provenance_count':len(prov_target),'definition_status':'INSUFFICIENT_BILATERAL_DEFINITION_EVIDENCE' if raw_definitions['bilateral_raw_definition_candidates']==0 else 'BILATERAL_DEFINITION_EVIDENCE_AVAILABLE'}
 result={'status':'EVALUATED','population':len(refs),'target_corpus_size':len(target0),'p0':p0['metrics'],'p1':p1['metrics'],'paired_rank_changes':changes,'alias_replication':'SUPPORTED_ON_SECOND_PAIR' if p1['metrics']['overall']['r_at_1']>p0['metrics']['overall']['r_at_1'] else 'NOT_REPLICATED' if cov1['source_aliases'] else 'INSUFFICIENT_ALIAS_EVIDENCE_FOR_REPLICATION','no_production_policy_change':True}
 hard_negative={'status':'DESCRIPTIVE_FULL_CORPUS_AUDIT','fixed_shared_top_k_selector_experiment':'NOT_RUN_NOT_PREDECLARED','p0':hard_negative_audit(source0,target0,refs),'interpretation':'Specific wrong-target recurrence is descriptive only; no semantic reranker or routing rule was constructed.'}
 cross_dataset={'status':'DESCRIPTIVE_ONLY','anatomy_p0':{'r_at_1':0.8016,'mrr':0.8433},'anatomy_p1':{'r_at_1':0.8550,'mrr':0.8914},'dh_p0':result['p0'],'dh_p1':result['p1'],'comparability_limitations':['different domain','different ontology representation','different corpus size','different reference population']}
 for name,value in [('EVIDENCE_COVERAGE.json',evidence),('RESULT.json',result),('HARD_NEGATIVE.json',hard_negative),('CROSS_DATASET.json',cross_dataset)]: wj(ARCHIVE/name,value)
 manifest={'schema_version':'v3_external_dh_v1','source_manifest_sha256':h(ARCHIVE/'SOURCE_MANIFEST.json'),'qualification_sha256':h(ARCHIVE/'QUALIFICATION.json'),'selected_pair_manifest_sha256':h(ARCHIVE/'SELECTED_PAIR_MANIFEST.json'),'evidence_coverage_sha256':h(ARCHIVE/'EVIDENCE_COVERAGE.json'),'result_sha256':h(ARCHIVE/'RESULT.json'),'hard_negative_sha256':h(ARCHIVE/'HARD_NEGATIVE.json'),'cross_dataset_sha256':h(ARCHIVE/'CROSS_DATASET.json'),'selection_precedes_evaluation':True}
 wj(ARCHIVE/'MANIFEST.json',manifest)
 wm(ROOT/'experiments/V3_EXTERNAL_DH_PAIR_QUALIFICATION.md','# V3 External DH Pair Qualification\n\n**QUALIFIED** for research-only external evaluation before scoring. The frozen iDAI.world English source contains '+str(len(source0))+' SKOS concepts; the PACTOLS English target contains '+str(len(target0))+'; the manual reference has '+str(len(refs))+' usable `=` mappings to '+str(len(set(refs.values())))+' unique targets. This is a documented non-injective target reuse, but every source has one unambiguous gold target and there are no source mapping conflicts. The candidate has stable URI identifiers and all mapped labels are readable.\n\nThe benchmark repository is MIT; its documented adapted iDAI.world and PACTOLS terms are CC BY 4.0 and ODbL v1.0 respectively. Use remains attribution- and ODbL-notice-aware research evaluation, not legal advice. Exact raw URLs, commit, bytes, and SHA-256 values are frozen in `SOURCE_MANIFEST.json`; qualification and the selected-pair manifest were persisted before metric computation. This is not a production ingestion path.')
 inventory_rows=evidence['predicate_inventory']['source_p1']+evidence['predicate_inventory']['target_p1']
 wm(ROOT/'experiments/V3_EXTERNAL_DH_EVIDENCE_COVERAGE.md','# V3 External DH Evidence Coverage\n\n'+table(['Field','P0','P1'],[[k,str(cov0[k]),str(cov1[k])] for k in cov1])+ '\n\n'+table(['Raw definition field','Mapped cases'],[[k,str(v)] for k,v in raw_definitions.items()])+ '\n\n'+table(['Ontology / predicate','Count','Profile field','P1 extracted / status'],[[('source ' if index < len(evidence['predicate_inventory']['source_p1']) else 'target ')+str(row['predicate']),str(row['count']),str(row['profile_field']),str(row['extracted'])+' / '+str(row['status'])] for index,row in enumerate(inventory_rows)])+f'\n\nDefinition status: `{evidence["definition_status"]}`. `dcterms:description` is audited as a standard definition-like predicate but is not silently added to P0/P1. SKOS `prefLabel`, `altLabel`, `definition`, and `broader`/`narrower` were consumed only in the research extractor. P0 keeps alias extraction disabled; P1 enables it without replacing labels.')
 def metric(which,key): return result[which]['overall'][key]
 wm(ROOT/'experiments/V3_EXTERNAL_DH_P0_P1_RESULT.md','# V3 External DH P0/P1 Result\n\n**MEASURED RESULT:** identical '+str(len(refs))+'-case population and '+str(len(target0))+'-concept target corpus.\n\n'+table(['Metric','P0 overall','P1 overall','P0 non-trivial','P1 non-trivial'],[[k,f'{result["p0"]["overall"][k]:.4f}',f'{result["p1"]["overall"][k]:.4f}',f'{result["p0"]["nontrivial"][k]:.4f}',f'{result["p1"]["nontrivial"][k]:.4f}'] for k in ('r_at_1','r_at_5','r_at_10','r_at_20','mrr')])+ '\n\n'+table(['Paired change','Count'],[[k,str(v)] for k,v in sorted(changes.items())])+f'\n\nAlias replication status: `{result["alias_replication"]}`. No weights, thresholds, or policies changed.')
 wm(ROOT/'experiments/V3_EXTERNAL_DH_HARD_NEGATIVE.md','# V3 External DH Hard Negative\n\nA descriptive full-corpus P0 audit found '+str(len(hard_negative['p0']['recurring_wrong_targets']))+' wrong targets recurring across the '+str(len(refs))+' frozen reference cases. The detailed target-ID counts are persisted in `HARD_NEGATIVE.json`. Fixed shared-Top-K semantic selection was **not run** because it was not predeclared; no substitute values or routing rule were fabricated.')
 wm(ROOT/'experiments/V3_EXTERNAL_DH_CROSS_DATASET_COMPARISON.md','# V3 External DH Cross-Dataset Comparison\n\n'+table(['Metric','Anatomy P0','Anatomy P1','DH P0','DH P1'],[['R@1','0.8016','0.8550',f'{metric("p0","r_at_1"):.4f}',f'{metric("p1","r_at_1"):.4f}'],['MRR','0.8433','0.8914',f'{metric("p0","mrr"):.4f}',f'{metric("p1","mrr"):.4f}']])+ '\n\nDirection is compared only; OWL Anatomy and SKOS archaeology differ materially in corpus, representation, and difficulty.')
 wm(ROOT/'experiments/V3_EXTERNAL_DH_RESEARCH_GATE.md','# V3 External DH Research Gate\n\n'+table(['Area','Status','Evidence'],[['external pair qualification','QUALIFIED','Frozen before scoring.'],['external provenance/license','SUPPORTED','MIT benchmark; CC BY 4.0/ODbL vocabulary terms recorded.'],['alias replication',result['alias_replication'],'Frozen P0/P1 comparison.'],['definition utility',evidence['definition_status'],'Coverage measured; no definition score fabricated.'],['representation portability','PARTIALLY_SUPPORTED','SKOS research extractor executed.'],['relation diversity','RELATION_DIVERSITY_EVIDENCE_GAP','All reference relations are equivalence.'],['Dense','RUNTIME_BLOCKER','Unchanged.'],['Qwen','UNAVAILABLE','Unchanged.'],['commitment calibration','DATA_MISSING','Independent evaluation pair is not calibration data.'],['Phase 3','NOT_SUPPORTED','Calibration and broader replication still absent.']])+ '\n\nNo policy, production profile, routing, threshold, calibration, canonical-KG, automatic-commitment, QSEM V1, or Dense-contract change.')
 return result
if __name__=='__main__': run()
